using ITServiceDeskApp.Data;
using ITServiceDeskApp.Models;
using ITServiceDeskApp.Services;
using ITServiceDeskApp.Controllers;
using ITServiceDeskApp.Security;
using ITServiceDeskApp.ViewModels.Operaciones;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.Extensions.Logging.Abstractions;
using System.Security.Claims;
void Check(bool value,string message){if(!value)throw new Exception(message);Console.WriteLine("PASS: "+message);}
var data=OperationalBreakdownCatalog.Missing([]);
Check(data.Count==1607,"All 1607 source rows imported, without invented records");
Check(data.Select(x=>x.SourceKey).Distinct().Count()==1607,"Every source row has an independent identity, including repeated events");
Check(OperationalBreakdownCatalog.Missing(data.Select(x=>x.SourceKey)).Count==0,"Reimport is idempotent");
Check(data.All(x=>x.Circuit=="Limón" && x.SourceJson!=null),"Original columns retained and source circuit preserved");
Check(OperationalBreakdownCatalog.Rows.Where(x=>x.Get("Fecha Fin Evento").Length>0).All(x=>OperationalBreakdownCatalog.Date(x.Get("Fecha Fin Evento"))!=null),"All nonempty closing dates parsed");
foreach(var row in data)foreach(var property in typeof(OperationalBreakdown).GetProperties()){
 var max=(System.ComponentModel.DataAnnotations.MaxLengthAttribute?)Attribute.GetCustomAttribute(property,typeof(System.ComponentModel.DataAnnotations.MaxLengthAttribute));
 if(max!=null && property.GetValue(row) is string text && text.Length>max.Length)throw new Exception("Length overflow: "+property.Name+" "+row.SourceKey);
}
using var db=new ApplicationDbContext(new DbContextOptionsBuilder<ApplicationDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);
OperationalBreakdownCatalog.Seed(db);OperationalBreakdownCatalog.Seed(db);
Check(db.OperationalBreakdowns.Count()==1607,"Startup import is idempotent in isolated database");
var truck=new OperationalMasterRecord{Kind="equipos",Name="W-0001",RecordKey="test-truck"};
db.Add(truck);db.SaveChanges();
var store=new OperacionesSeguimientoStore(db);
OperacionesController Controller(string? profile=null){
 var claims=new List<Claim>{new(ClaimTypes.Email,profile==null?"monitoreo@trawzacons.com":"supervisor@example.com"),new(ClaimTypes.Role,"Administrator")};
 if(profile!=null)claims.Add(new(UserAccessProfiles.ClaimType,profile));
 var http=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity(claims,"test"))};
 return new OperacionesController(null!,store,null!,null!,null!,null!,db,null!,null!,NullLogger<OperacionesController>.Instance,null!,null!){ControllerContext=new ControllerContext{HttpContext=http},TempData=new TempDataDictionary(http,new TempData())};
}
var form=(BreakdownCreateViewModel)((ViewResult)Controller().NuevaAveria("master:"+truck.Id)).Model!;
Check(form.Equipment==truck.Name && form.Circuit=="Limón","Truck menu preselects equipment and defaults circuit to Limón");
var category=OperationalBreakdownCatalog.Elements.First();
BreakdownCreateViewModel Valid()=>new(){Equipment=truck.Name,EquipmentStatus="Vacio",Category=category.Key,Element=category.Value.First(),DamageTarget="EQUIPO"};
Check(await Controller().NuevaAveria(Valid(),default) is RedirectToActionResult,"Authorized user can register new breakdown");
Check(db.OperationalBreakdowns.Count()==1608 && db.OperationalBreakdowns.OrderBy(x=>x.Id).Last().Status=="Abierta","Manual record is saved as open and historical count preserved");
var invalid=Valid();invalid.Element="INVALID";
Check(await Controller().NuevaAveria(invalid,default) is ViewResult && db.OperationalBreakdowns.Count()==1608,"Unrelated damage element rejected without saving");
Check(await Controller(UserAccessProfiles.SupervisorOperations).NuevaAveria(Valid(),default) is ForbidResult,"Read-only supervisor cannot create breakdowns");
Check(((BreakdownListViewModel)((ViewResult)await Controller().Averias(null,1)).Model!).Records.Count==50,"Historical table paginates at 50 rows");
using var pg=new PostgresApplicationDbContext(new DbContextOptionsBuilder<PostgresApplicationDbContext>().UseNpgsql("Host=localhost;Database=check;Username=check;Password=unused").Options);
Check(pg.GetService<IMigrator>().GenerateScript("20261028010000_FleetDriverAssignmentsPostgres","20261029010000_OperationalBreakdownsPostgres").Contains("OperationalBreakdowns"),"PostgreSQL migration script generated without connecting");
using var sql=new ApplicationDbContext(new DbContextOptionsBuilder<ApplicationDbContext>().UseSqlServer("Server=localhost;Database=check;Integrated Security=True;TrustServerCertificate=True").Options);
Check(sql.GetService<IMigrator>().GenerateScript("20261028010000_FleetDriverAssignments","20261029010000_OperationalBreakdowns").Contains("OperationalBreakdowns"),"SQL Server migration script generated without connecting");
var boardTime=new DateTime(2026,10,29,18,0,0,DateTimeKind.Utc);
OperationalBreakdown Open(int id,string? source=null)=>new(){Id=id,Equipment="W-0001",EventAt=new DateTime(2026,10,29,10,0,0),Status="Abierta",SourceJson=source};
var road=Open(1,"{\"Sitio\":\"Carretera\"}");var workshop=Open(2,"{\"Sitio\":\"Plantel Central\"}");
var closed=Open(3);closed.Status="Cerrada";
var ended=Open(4);ended.EndAt=boardTime;
var board=MaintenanceBreakdownBoard.Build(new[]{road,workshop,closed,ended,Open(5)},[],boardTime);
Check(board.Count==3 && board.Any(x=>x.Site=="Carretera") && board.Any(x=>x.Site=="Plantel Central"),"Maintenance board includes open roadside and workshop breakdowns and excludes closed/ended records");
Check(board.Single(x=>x.Id==5).Site=="Sin ubicación registrada","Missing location does not hide an open breakdown");
Check(board.All(x=>x.ElapsedHours==2),"Elapsed time uses Nicaragua timezone");
Check(MaintenanceBreakdownBoard.Build(new[]{Open(6)},new[]{new OperationalFleetState{EquipmentCode="W-0001",Status="taller-psb"}},boardTime).Single().Site=="PSB","Unlocated breakdown uses the equipment's manual workshop classification");
Check(MaintenanceBreakdownBoard.Build(new[]{Open(7,"invalid json")},[],boardTime).Count==1,"Malformed legacy metadata cannot hide open breakdowns");
Check(MaintenanceBreakdownBoard.Build(new[]{Open(8,"{\"VIGENCIA\":\"NULO\"}")},[],boardTime).Count==0,"Voided source records never appear as operationally open");
Check(MaintenanceBreakdownBoard.Build(new[]{Open(9,"{\"Estatus\":\"Cerrada\"}")},[],boardTime).Count==0,"Source closure overrides a stale open status");
Check(MaintenanceBreakdownBoard.Build(new[]{Open(10,"{\"Fecha Fin Evento\":\"29/10/2026 10:00:00\"}")},[],boardTime).Count==0,"Source closing date overrides a stale empty EndAt");
Check(MaintenanceBreakdownBoard.Build(data,[],boardTime).Count==94,"Only the 94 valid open historical records reach the maintenance board");
var closeTruck=new OperationalMasterRecord{Kind="equipos",Name="W-CLOSE",Plate="M-CLOSE",RecordKey="close-truck"};
db.Add(closeTruck);db.SaveChanges();
var first=Open(0);first.Equipment=closeTruck.Name;
var second=Open(0);second.Equipment=closeTruck.Plate!;
db.AddRange(first,second);db.SaveChanges();
var result=await OperationalBreakdownClosure.CloseAsync(db,new(),first.Id,new DateTime(2026,10,29,9,0,0),"admin@trawzacons.com",boardTime);
Check(result.Error!=null && first.EndAt==null,"Closing before event start is rejected");
result=await OperationalBreakdownClosure.CloseAsync(db,new(),first.Id,new DateTime(2026,10,29,13,0,0),"admin@trawzacons.com",boardTime);
Check(result.Error!=null && first.EndAt==null,"Future closing date is rejected in Nicaragua timezone");
result=await OperationalBreakdownClosure.CloseAsync(db,new(),first.Id,new DateTime(2026,10,29,11,0,0),"admin@trawzacons.com",boardTime);
Check(result.Error==null && !result.Activated && first.Status=="Cerrada" && first.EndAt!=null,"Closing one incident cannot activate equipment with another open incident, including plate aliases");
Check(!MaintenanceBreakdownBoard.IsOperationallyOpen(first) && first.SourceJson!.Contains("admin@trawzacons.com"),"Closure leaves maintenance board and records closing actor");
var priorUpload=new SeguimientoToneladasViewModel{IsFromUpload=true,LatestUploadAt=boardTime.AddMinutes(-10),LatestUploadEquipment=[closeTruck.Name],Rows=[new(){Equipo=closeTruck.Name,Estado="EN RUTA",FechaEvento=boardTime}]};
result=await OperationalBreakdownClosure.CloseAsync(db,priorUpload,second.Id,new DateTime(2026,10,29,11,30,0),"admin@trawzacons.com",boardTime);
Check(result.Error==null && result.Activated,"Closing the last incident activates equipment");
Check(OperationalFleetBoard.Build(db.OperationalMasterRecords.ToList(),priorUpload,db.OperationalFleetStates.ToList()).Equipment.Single(x=>x.Code==closeTruck.Name).Status=="finalizado","Closure activation moves truck to discharged even when the previous TiHouse row says en route");
result=await OperationalBreakdownClosure.CloseAsync(db,new(),second.Id,new DateTime(2026,10,29,11,45,0),"admin@trawzacons.com",boardTime);
Check(result.Error!=null && second.EndAt==new DateTime(2026,10,29,11,30,0),"Repeated closure cannot overwrite stored closing time or activate equipment again");
var manager=new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.Email,"taller@example.com"),new Claim(UserAccessProfiles.ClaimType,UserAccessProfiles.MaintenanceEditor)},"test"));
Check(OperationalBreakdownClosure.CanClose(manager),"Maintenance editor may close incidents");
var supervisor=new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.Email,"supervisor@example.com"),new Claim(UserAccessProfiles.ClaimType,UserAccessProfiles.SupervisorOperations)},"test"));
Check(!OperationalBreakdownClosure.CanClose(supervisor),"Read-only operations supervisor cannot close incidents");
Console.WriteLine("PASS: Averias, maintenance-board and closure acceptance checks complete");
sealed class TempData:ITempDataProvider{public IDictionary<string,object> LoadTempData(HttpContext c)=>new Dictionary<string,object>();public void SaveTempData(HttpContext c,IDictionary<string,object> v){}}


